-- Domain: product_catalog
-- Owner: retailpulses/RPagentOS
-- Affected: public.platform_listings
-- Change class: data
-- Hosted write required: yes
-- Consumers: retailpulses/CatalogSync, retailpulses/ticket-handling
-- Issues: https://github.com/retailpulses/RPagentOS/issues/105, https://github.com/retailpulses/RPagentOS/issues/108
-- Forward recovery: rerun this idempotent migration after correcting exact input rows.
-- Rollback: preserve populated prices; any correction must target explicit Shop4 listing IDs.
-- Excludes two fee/shipping adjustment-only records absent from platform_listings:
-- 2JUSPhPbREyHNLqyJPBfM8 (RP004-R), 2JTfXGaA7DjPggYVHRsMLu (N00000003).

BEGIN;

ALTER TABLE public.platform_listings
  ADD COLUMN IF NOT EXISTS mercari_before_discount_price numeric(12,2);

ALTER TABLE public.platform_listings
  ADD CONSTRAINT platform_listings_mercari_before_discount_price_positive
  CHECK (mercari_before_discount_price IS NULL OR mercari_before_discount_price > 0);

CREATE TEMP TABLE shop4_listing_price_input (
  external_listing_id text PRIMARY KEY,
  seller_sku text NOT NULL,
  current_price numeric(12,2) NOT NULL CHECK (current_price > 0),
  mercari_before_discount_price numeric(12,2) NOT NULL CHECK (mercari_before_discount_price > 0)
) ON COMMIT DROP;

