DO $$
DECLARE
  input_count integer;
  listing_match_count integer;
  sku_match_count integer;
BEGIN
  SELECT count(*) INTO input_count FROM shop4_listing_price_input;
  IF input_count <> 2590 THEN
    RAISE EXCEPTION 'expected 2590 input rows, got %', input_count;
  END IF;

  SELECT count(*) INTO listing_match_count
  FROM shop4_listing_price_input i
  JOIN public.platform_listings l
    ON l.platform = 'mercari' AND l.shop_code = 'shop4'
   AND l.external_listing_id = i.external_listing_id;
  IF listing_match_count <> input_count THEN
    RAISE EXCEPTION 'Shop4 listing match mismatch: input %, matched %', input_count, listing_match_count;
  END IF;

  SELECT count(*) INTO sku_match_count
  FROM shop4_listing_price_input i
  JOIN public.platform_listings l
    ON l.platform = 'mercari' AND l.shop_code = 'shop4'
   AND l.external_listing_id = i.external_listing_id
  WHERE EXISTS (
    SELECT 1 FROM public.platform_listing_skus s
    WHERE s.listing_id = l.id AND (s.seller_sku = i.seller_sku OR s.sku_code = i.seller_sku)
  );
  IF sku_match_count <> input_count THEN
    RAISE EXCEPTION 'Shop4 SKU match mismatch: input %, matched %', input_count, sku_match_count;
  END IF;

  RAISE NOTICE 'Shop4 price audit passed: % listings and SKUs matched', input_count;
END $$;

-- Five deterministic canaries first, still inside the all-or-nothing transaction.
WITH canary AS (
  SELECT * FROM shop4_listing_price_input ORDER BY external_listing_id LIMIT 5
)
UPDATE public.platform_listings l
SET current_price = c.current_price,
    mercari_before_discount_price = c.mercari_before_discount_price,
    updated_at = now()
FROM canary c
WHERE l.platform = 'mercari' AND l.shop_code = 'shop4'
  AND l.external_listing_id = c.external_listing_id
  AND (l.current_price, l.mercari_before_discount_price)
      IS DISTINCT FROM (c.current_price, c.mercari_before_discount_price);

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM (SELECT * FROM shop4_listing_price_input ORDER BY external_listing_id LIMIT 5) c
    JOIN public.platform_listings l ON l.platform='mercari' AND l.shop_code='shop4'
      AND l.external_listing_id=c.external_listing_id
    WHERE (l.current_price, l.mercari_before_discount_price)
          IS DISTINCT FROM (c.current_price, c.mercari_before_discount_price)
  ) THEN RAISE EXCEPTION 'Shop4 canary readback mismatch'; END IF;
END $$;

UPDATE public.platform_listings l
SET current_price = i.current_price,
    mercari_before_discount_price = i.mercari_before_discount_price,
    updated_at = now()
FROM shop4_listing_price_input i
WHERE l.platform = 'mercari' AND l.shop_code = 'shop4'
  AND l.external_listing_id = i.external_listing_id
  AND (l.current_price, l.mercari_before_discount_price)
      IS DISTINCT FROM (i.current_price, i.mercari_before_discount_price);

DO $$
DECLARE verified integer;
BEGIN
  SELECT count(*) INTO verified
  FROM shop4_listing_price_input i
  JOIN public.platform_listings l ON l.platform='mercari' AND l.shop_code='shop4'
    AND l.external_listing_id=i.external_listing_id
  WHERE (l.current_price, l.mercari_before_discount_price)
        IS NOT DISTINCT FROM (i.current_price, i.mercari_before_discount_price);
  IF verified <> 2590 THEN RAISE EXCEPTION 'final readback mismatch: %', verified; END IF;
  RAISE NOTICE 'Shop4 price import verified: % rows', verified;
END $$;

COMMIT;
